export type AsyncActionStatus = 'idle' | 'pending' | 'success' | 'error';

export type AsyncActionOptions = {
	action: () => unknown;
	resetAfter?: number;
	onError?: (error: unknown) => void;
};

export class AsyncActionState {
	#read: () => AsyncActionOptions;

	#status = $state<AsyncActionStatus>('idle');

	#timer: ReturnType<typeof setTimeout> | undefined;
	#runId = 0;
	#alive = true;

	constructor(options: AsyncActionOptions | (() => AsyncActionOptions)) {
		this.#read = typeof options === 'function' ? options : () => options;

		$effect(() => {
			this.#alive = true;
			return () => {
				this.#alive = false;
				clearTimeout(this.#timer);
			};
		});
	}

	get status() {
		return this.#status;
	}

	get pending() {
		return this.#status === 'pending';
	}

	reset = () => {
		clearTimeout(this.#timer);
		this.#runId += 1;
		this.#status = 'idle';
	};

	#settle(id: number, next: 'success' | 'error') {
		if (!this.#alive || id !== this.#runId) return;

		clearTimeout(this.#timer);
		this.#status = next;
		this.#timer = setTimeout(() => {
			if (!this.#alive || id !== this.#runId) return;
			this.#status = 'idle';
		}, this.#read().resetAfter ?? 1400);
	}

	run = async () => {
		if (this.pending) return;

		clearTimeout(this.#timer);
		const id = ++this.#runId;
		this.#status = 'pending';

		try {
			await this.#read().action();
			this.#settle(id, 'success');
		} catch (error) {
			this.#read().onError?.(error);
			this.#settle(id, 'error');
		}
	};
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge class values, resolving Tailwind conflicts so the last one wins.
 *
 * This is what makes the `class` prop on every component behave the way the
 * registry documents it: "appended last to the root, so width and spacing are
 * the caller's". Plain concatenation would leave both `p-2` and the caller's
 * `p-4` in the list and let source order in the stylesheet decide; `twMerge`
 * drops the loser outright.
 *
 * Design-language classes from `layout.css` (`mat-panel`, `press`, `tnum`, …)
 * are not utilities, so `twMerge` passes them through untouched.
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
